import * as G from './journey.js?v=2.0.1';
import * as F from './game.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(n,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const portrait=(n,cls='')=>`<div class="portrait ${cls}" style="--px:${n%4/3*100}%;--py:${Math.floor(n/4)*100}%" aria-hidden="true"></div>`;
const num=n=>Math.floor(n).toLocaleString('vi-VN'), pad=n=>String(n).padStart(2,'0');
const btn=(label,action,id='',cls='secondary',disabled=false)=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}" ${disabled?'disabled':''}>${label}</button>`;
const pill=(text,cls='')=>`<span class="badge ${cls}">${text}</span>`;
const clockText=()=>{const c=G.calendar(state);return `Năm ${c.year} · ${pad(c.day)}/${pad(c.month)} · ${pad(c.hour)}:${pad(c.minute)}`;};
const sectName=()=>state.path==='founder'?state.sectName:G.sect(state)?.name||'Tiên đồ chưa định';
const q=new URLSearchParams(location.search),isPreview=q.get('preview')==='1',KEY='thanh-van-tong-v2';
let initial;try{initial=isPreview?{state:G.preview(q.get('scenario')||'mortal'),offline:null}:G.restore(localStorage.getItem(KEY));}catch{initial={state:G.newGame(),offline:null,recovered:true};}
let state=initial.state,screen='home',tab='',page=0,battleSpeed=1,battleTimer=null,dialogKind='',saveFailed=false,audioContext;
const tabs={admission:[['all','Sơn môn']],sect:[['missions','Nhiệm vụ'],['shop','Đổi đồ'],['rank','Chức danh'],['found','Khai tông']],cultivation:[['practice','Tu luyện'],['manuals','Công pháp'],['alchemy','Luyện đan']],activity:[['travel','Lịch luyện'],['dungeons','Bí cảnh'],['annual','Đại tỷ'],['relations','Quan hệ'],['story','Cốt truyện']],bag:[['pills','Đan dược'],['artifacts','Pháp bảo'],['materials','Nguyên liệu'],['log','Nhật ký']]};
function persist(){if(isPreview)return;try{localStorage.setItem(KEY,JSON.stringify(state));saveFailed=false;}catch{if(!saveFailed)toast('Chưa lưu được trên trình duyệt. Hãy xuất bản lưu trong Cài đặt.');saveFailed=true;}}
function toast(message){const e=document.createElement('div');e.className='toast';e.textContent=message;$('#toasts').append(e);setTimeout(()=>e.remove(),4000);}
function sound(){if(!state.sound)return;try{audioContext||=new AudioContext();const o=audioContext.createOscillator(),g=audioContext.createGain();o.connect(g);g.connect(audioContext.destination);o.frequency.setValueAtTime(660,audioContext.currentTime);g.gain.setValueAtTime(.025,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.12);o.start();o.stop(audioContext.currentTime+.12);}catch{}}
function openScreen(next,nextTab){if(next!=='home'&&next!=='admission'&&state.path==='mortal'){next='admission';toast('Hãy vượt khảo hạch và nhập đạo trước.');}screen=next;tab=nextTab||tabs[next]?.[0]?.[0]||'';page=0;render();}
function card(title,desc,meta,action,decoration=icon('scroll'),cls=''){return `<article class="function-card ${cls}"><div class="card-top"><div class="card-emblem">${decoration}</div><div><h3>${title}</h3><div class="card-meta">${meta||''}</div></div></div><p>${desc}</p><div class="card-action">${action||''}</div></article>`;}
function header(){const c=G.calendar(state);$('#game-header').innerHTML=`<a class="wordmark" href="#" data-action="home">${icon('mountain')}<span><strong>Tu Tiên Vấn Đạo</strong><small>THANH VÂN TÔNG</small></span></a><div class="resource-strip"><div title="Linh thạch">${icon('stone')}<span data-live="stone">${num(state.stone)}</span><small>Linh thạch</small></div><div title="Cống hiến có thể dùng để đổi đồ">${icon('scroll')}<span data-live="contribution">${num(state.contribution)}</span><small>Cống hiến</small></div><div class="power-resource">${icon('sword')}<span data-live="power">${num(G.power(state))}</span><small>Chiến lực</small></div></div><div class="header-end"><span class="calendar" data-live="calendar">${clockText()}</span><button class="icon-button" data-action="settings" aria-label="Cài đặt và lưu game">${icon('settings')}</button></div>`;$('#bottom-nav').innerHTML=[['home','home','Hành trình'],['sect','mountain','Tông môn'],['cultivation','qi','Tu luyện'],['activity','sword','Hoạt động'],['bag','bag','Túi đồ']].map(([id,ic,label])=>`<button data-action="nav" data-id="${id}" class="nav-button ${screen===id||screen==='admission'&&id==='sect'?'active':''}">${icon(ic)}<span>${label}</span>${id==='activity'&&(state.pendingEvent||state.annualYears.length)?'<i class="notification"></i>':''}</button>`).join('');$('#clock-hint').textContent=`${clockText()} · 1 giây = 1 phút${isPreview?' · Xem thử':''}`;}
function homeMarkup(){const mortal=state.path==='mortal',b=G.BOOKS.find(x=>x.id===state.technique),activity=state.activity;const title=mortal?'Một đời phàm nhân.\nMột bước tiên đồ.':state.path==='founder'?'Khai sơn lập phái.\nViết đạo của riêng mình.':'Giữa mây ngàn,\ncon đường còn phía trước.';
return `<div class="home-layout"><div class="world-shade"></div><section class="player-panel"><div class="player-summary">${portrait(state.portrait,'avatar')}<div><span class="eyebrow">${mortal?'NGƯỜI TÌM ĐẠO':esc(sectName())}</span><h1>${esc(state.name)}</h1><div class="player-badges">${pill(G.rankName(state),'gold')}${pill(G.realmName(state))}</div></div>${btn(icon('users'),'profile','','icon-button',false)}</div><div class="cultivation-summary">${mortal?`<p>16 tuổi · Phàm nhân chưa có tu vi</p><div class="mortal-measures"><span>${state.root?esc(state.root.quality):'Linh căn chưa đo'}</span><span>${state.potential===null?'Tư chất chưa đo':state.potential+'/100 tư chất'}</span></div>`:`<div class="meter-label"><span>${icon('qi')} Tu vi <b data-live="xp">${num(state.xp)} / ${num(G.goal(state))}</b></span><span data-live="rate">${state.training?'Đang tu luyện':'Tạm nghỉ'}</span></div><div class="progress"><i data-live="xpbar" style="width:${Math.min(100,state.xp/G.goal(state)*100)}%"></i></div><p>${esc(b?.name||'Dẫn Khí Quyết')} · Tổng cống hiến ${num(state.merit)}</p>`}</div></section><div class="scene-heading"><span class="eyebrow">${mortal?'CHƯƠNG I · DƯỚI CHÂN SƠN MÔN':'CHƯƠNG II · NHẤT TÂM VẤN ĐẠO'}</span><h2>${title.split('\n').join('<br>')}</h2><p>${mortal?'Sáu tông môn, sáu con đường. Tiên duyên bắt đầu từ chính lựa chọn của bạn.':'Tu luyện, kết giao, khám phá cơ duyên giữa thiên địa.'}</p></div><div class="hero-unit"><div class="qi-ring"></div>${portrait(state.portrait,'hero-art')}<div class="hero-label">${esc(state.name)}<small>${G.realmName(state)}</small></div></div><div class="scene-pin pin-one">${icon('home')}<span>Chính điện</span></div><div class="scene-pin pin-two">${icon('mountain')}<span>Sơn môn</span></div><section class="home-bottom"><div class="current-goal"><span class="eyebrow">${activity?'ĐANG THỰC HIỆN':state.pendingEvent?'CƠ DUYÊN MỚI':'BƯỚC TIẾP THEO'}</span><strong data-live="activity">${activity?esc(activity.name)+' · '+Math.max(0,Math.ceil(activity.finish-state.gameMinutes))+' giây':mortal?'Chọn tông môn và tham dự khảo hạch':state.pendingEvent?G.STORIES[state.pendingEvent.id].name:state.annualYears.length?'Đại tỷ tông môn đã khai hội':state.rank<7&&state.path==='member'?'Tích lũy cống hiến, tỷ thí để thăng chức':'Lịch luyện và phát triển tiên đồ'}</strong>${activity?'<div class="progress small"><i data-live="activitybar"></i></div>':''}</div><div class="home-actions">${mortal?btn(`Xin khảo hạch ${icon('arrow')}`,'nav','admission','primary')+btn('Đổi tên nhân vật','profile'):btn(`${icon('qi')} ${state.training?'Đang bế quan':'Bắt đầu tu luyện'}`,'training','','primary')+btn('Tĩnh tâm + tu vi','meditate')+btn(state.pendingEvent?'Xem cơ duyên':'Nhận nhiệm vụ','nav',state.pendingEvent?'story':'missions')}</div></section><button class="guide-button" data-action="help" aria-label="Hướng dẫn chơi">?</button></div>`;}
function pageLayout(){const w=innerWidth,cols=w>=1100?3:w>=720?2:1,small=w<720;const frameHeight=$('#game-view').clientHeight||innerHeight-(small?164:148);const reserved=(screen==='admission'?(small?266:238):small?215:230)+(screen==='sect'&&state.foundation&&(tab==='found'||tab==='disciples')?35:0);const rows=Math.max(1,Math.min(3,Math.floor((frameHeight-reserved)/(cols>1?190:150))));return {cols,rows,size:cols*rows};}
function screenData(){const s=state;let title='',subtitle='',cards=[];if(screen==='admission'){title='Sơn môn cầu đạo';subtitle='Đo linh căn → đo tư chất → chọn tông môn → thử đạo tâm';cards=G.SECTS.map(x=>{const score=G.examScore(s,x.id),ready=s.root&&s.potential!==null;return card(esc(x.name),esc(x.desc),pill(x.element+' hệ')+pill(x.min?'Yêu cầu '+x.min+' điểm':'Thu nhận mọi linh căn','gold'),btn(ready?'Khảo hạch · '+score+' điểm':'Xem khảo hạch','exam',x.id,'primary'),icon('mountain'),'sect-style-'+x.style);});}
if(screen==='sect'){title=s.path==='founder'?esc(s.sectName):esc(sectName());subtitle=s.path==='founder'?'Tông môn vận hành tự động theo phân công đệ tử.':'Cống hiến hôm nay, đặt nền cho tiên đồ ngày mai.';
if(tab==='missions')cards=G.MISSIONS.map(m=>card(m.name,m.desc,pill(G.RANKS[m.rank])+pill(m.minutes+' giây thực'),`<span class="reward-text">+${m.contribution} cống hiến · +${m.stone} linh thạch</span>${btn(s.activity?'Đang có việc':s.rank<m.rank&&s.path!=='founder'?'Chưa đủ chức danh':'Nhận nhiệm vụ','mission',m.id,'primary',!!s.activity||s.rank<m.rank&&s.path!=='founder')}`,icon('scroll')));
if(tab==='shop')cards=G.SHOP.map(x=>card(x.name,x.desc,pill(x.kind==='book'?'Công pháp':x.kind==='artifact'?'Pháp bảo':'Đan dược'),`<span class="reward-text">${x.cost} cống hiến · Có ${s.items[x.id]||0}</span>${btn('Đổi vật phẩm','buy',x.id,'primary',s.contribution<x.cost)}`,icon(x.kind==='pill'?'pill':x.kind==='artifact'?'sword':'scroll')));
if(tab==='rank'){const req=G.promotionRequirement(s),next=s.rank===4&&s.gender==='female'?'Thánh nữ':G.RANKS[Math.min(s.rank+1,7)];cards=[card('Chức danh hiện tại',s.path==='founder'?'Bạn đã khai tông, đang đi theo con đường tông chủ.':'Thăng chức bằng khảo hạch chiến đấu với đồng môn.',pill(G.rankName(s),'gold'),`<span class="reward-text">Đã thăng chức ${s.stats.promotions} lần</span>` ,portrait(s.portrait,'card-portrait')),card('Tỷ thí lên '+next,`Cần ${G.REALMS[req.realm]} tầng ${req.stage}, tổng cống hiến ${num(req.merit)}. Lệ phí ${20*(s.rank+1)} cống hiến.`,pill('Tu vi '+(G.eligible(s,req)?'đủ':'chưa đủ'))+pill('Cống hiến '+num(s.merit)+'/'+num(req.merit)),btn('Đăng ký tỷ thí','battle','promotion','primary',s.path!=='member'||s.rank>=7),icon('sword')),card('Con đường trong tông môn','Tạp dịch → Ngoại môn → Nội môn → Trọng tâm → Chân truyền → Thánh tử / Thánh nữ → Trưởng lão → Chưởng môn.',pill('8 chức danh'),btn('Hướng dẫn tu luyện','nav','practice'),icon('mountain'))];}
if(tab==='found'){if(s.path!=='founder')cards=[card('Khai sơn lập phái','Đạt Nguyên Anh, chuẩn bị 3.000 linh thạch, 120 linh mộc, 80 linh khoáng để sáng lập tông môn riêng.',pill('Nguyên Anh trở lên','gold'),btn('Đặt tên và khai tông','found','','primary'),icon('mountain')),card('Ở lại và nối tiếp đạo thống','Bạn có thể ở lại tông môn. Tỷ thí lần lượt lên Trưởng lão ở Nguyên Anh và Chưởng môn ở Hóa Thần.',pill('Lựa chọn của bạn'),btn('Xem chức danh','tab','rank'),icon('users')),card('Chuẩn bị khai tông','Lịch luyện để gom linh mộc, linh thảo và kết giao bạn hữu; nhiệm vụ và bí cảnh cho linh khoáng, linh thạch.',pill('Tài nguyên cá nhân'),btn('Đi lịch luyện','nav','travel'),icon('bag'))];else{cards=F.BUILDINGS.map(b=>{const f=s.foundation,c=F.upgradeCost(f,b.id);return card(b.name,b.desc,pill('Cấp '+f.buildings[b.id],'gold'),`<span class="reward-text">${num(c.stone)} thạch · ${num(c.wood)} mộc · ${num(c.ore)} khoáng</span>${btn('Nâng cấp','upgrade',b.id,'primary',f.buildings[b.id]>=10)}`,icon(b.resource==='stone'?'home':b.id==='alchemy'?'pill':b.id));});}}
if(tab==='disciples'&&s.foundation)cards=s.foundation.disciples.map(d=>card(esc(d.name),'Phân công tạo tài nguyên tự động cho tông môn.',pill(d.element)+pill(d.rarity),`<select data-job="${d.id}" aria-label="Phân công ${esc(d.name)}">${Object.entries(F.JOBS).map(([id,n])=>`<option value="${id}" ${id===d.job?'selected':''}>${n}</option>`).join('')}</select>`,portrait(d.appearance,'card-portrait')));
}
if(screen==='cultivation'){title='Nhất tâm tu luyện';subtitle='Tu vi tích lũy khi bế quan, cả khi bạn rời game.';
if(tab==='practice'){const c=G.breakthroughCost(s);cards=[card(G.realmName(s),'Tích lũy đủ tu vi sẽ tự tăng tầng. Tầng 9 đầy tu vi cần đột phá sang đại cảnh giới tiếp theo.',pill('Tu vi '+num(s.xp)+'/'+num(G.goal(s))),btn(s.training?'Tạm dừng bế quan':'Bắt đầu bế quan','training','','primary')+btn('Tĩnh tâm','meditate'),icon('qi')),card('Đột phá đại cảnh giới',`${num(c.stone)} linh thạch · ${c.herb} linh thảo${c.pills?' · '+c.pills+' Phá Cảnh Đan':''}. Đột phá thành công mở nhiệm vụ, bí cảnh và chức danh mới.`,pill('Tầng 9 · Tu vi đầy','gold'),btn('Đột phá','breakthrough','','primary',s.realm>=9),icon('mountain')),card('Linh căn và tư chất',`${G.rootName(s)}. Độ tinh thuần ${s.root?.purity||0}/100. Linh căn hợp tông môn và công pháp giúp tăng tốc độ tu luyện.`,pill('Tư chất '+s.potential+'/100')+pill('+'+G.trainingRate(s).toFixed(2)+' tu vi/giây'),btn('Xem nhân vật','profile'),portrait(s.portrait,'card-portrait'))];}
if(tab==='manuals'){cards=G.BOOKS.filter(b=>s.learned.includes(b.id)||s.items[b.id]>0).map(b=>card(b.name,b.desc,pill(b.grade,'gold')+pill(s.learned.includes(b.id)?'Đã lĩnh ngộ':'Chưa học'),btn(b.id===s.technique?'Đang vận dụng':s.learned.includes(b.id)?'Vận dụng':'Lĩnh ngộ','book',b.id,'primary',b.id===s.technique),icon('scroll')));}
if(tab==='alchemy')cards=[['pillQi','Tụ Khí Đan','45 linh thạch · 20 linh thảo. Nhận 90 tu vi khi dùng.'],['pillHeal','Hồi Nguyên Đan','30 linh thạch · 15 linh thảo. Tăng 25% sinh lực cho một trận.'],['pillBreak','Phá Cảnh Đan','180 linh thạch · 60 linh thảo · 20 linh khoáng. Dùng khi đột phá từ Trúc Cơ.']].map(([id,name,desc])=>card(name,desc,pill('Đang có '+(s.items[id]||0)),btn('Luyện một viên','craft',id,'primary'),icon('pill')));
}
if(screen==='activity'){title='Vạn dặm tiên duyên';subtitle='Lịch luyện, tỷ thí, gặp gỡ và lựa chọn giữa thiện duyên, ân oán.';
if(tab==='travel')cards=[card('Lịch luyện dưới núi','Mỗi chuyến có linh thạch, thảo dược, linh mộc và một vật phẩm ngẫu nhiên. Có thể kết giao bạn hữu hoặc gây hiềm khích.',pill('90 giây thực')+pill('Có cơ duyên','gold'),btn('Bắt đầu lịch luyện','travel','','primary',!!s.activity),icon('mountain')),card('Giao lưu các tông môn','Ngoại môn trở lên được cử đi giao lưu, trao đổi công pháp và kết giao tu sĩ. Lộ phí 30 linh thạch; mỗi ngày game đi một lần.',pill('240 giây thực')+pill('+55 cống hiến'),btn('Đi giao lưu','exchange','','primary',!!s.activity||s.rank<1&&s.path!=='founder'),icon('users')),card('Hoạt động hiện tại',s.activity?'Bạn vẫn tu luyện với 35% tốc độ khi làm nhiệm vụ hoặc lịch luyện. Phần thưởng tự nhận khi hoàn thành.':'Chọn một hoạt động. Khi tắt game, đồng hồ tiếp tục và phần thưởng vẫn được nhận một lần.',pill(s.activity?'Đang thực hiện':'Sẵn sàng'),`<span class="activity-status" data-live="activity">${s.activity?esc(s.activity.name)+' · '+Math.ceil(s.activity.finish-s.gameMinutes)+' giây':'Chưa có hoạt động'}</span>`,icon('scroll'))];
if(tab==='dungeons')cards=G.AREAS.map(a=>card(a.name,a.desc,pill(G.REALMS[a.realm]+' tầng '+a.stage),btn(G.eligible(s,a)?'Tiến vào bí cảnh':'Chưa đủ tu vi','dungeon',a.id,'primary',!G.eligible(s,a)),icon('sword'),'sect-style-'+a.style));
if(tab==='annual'){const until=Math.max(0,s.annualNext*G.YEAR-s.gameMinutes);cards=[card('Đại tỷ tông môn',s.annualYears.length?`Đại tỷ năm ${s.tournament?.year||s.annualYears[0]} đang mở. Vượt ba vòng chiến đấu để nhận linh thạch, cống hiến và công pháp.`:'Đại tỷ tổ chức sau mỗi 365 ngày trong game. Thời gian vẫn trôi khi bạn tắt game.',pill(s.annualYears.length?'Đã khai hội':'Chưa khai hội','gold'),btn(s.tournament?'Thi đấu vòng '+(s.tournament.round+1):'Tham dự đại tỷ','battle','annual','primary',!s.annualYears.length),icon('sword')),card('Lịch khai hội','1 giây thực = 1 phút game. Một năm game bằng 6 ngày 2 giờ thực. Khi vắng lâu, lưu tối đa ba kỳ đại tỷ gần nhất.',pill('365 ngày/năm'),`<span class="reward-text" data-live="annual">Kỳ tiếp theo sau ${realDuration(until)}</span>`,icon('scroll')),card('Thành tích','Chiến thắng từng vòng sẽ nhận thưởng. Thua một kỳ vẫn nhận 20 cống hiến và có thể tiếp tục tu luyện cho năm sau.',pill('Quán quân '+s.stats.annualWins+' lần'),`<span class="reward-text">${s.stats.wins} trận thắng · ${s.completedAnnual.length} kỳ đã hoàn tất</span>`,icon('users'))];}
if(tab==='relations')cards=s.contacts.map(p=>card(esc(p.name),p.affinity>=40?'Bạn hữu giúp tăng công kích thêm 4%, tối đa ba người. Thăm hỏi để duy trì quan hệ.':p.affinity<=-20?'Có hiềm khích; người này có thể tìm đến cửa yêu cầu tỷ thí. Thăm hỏi có thể làm dịu ân oán.':'Gặp lại, trao quà và luận đạo để xây dựng giao tình.',pill(G.relationship(p),p.affinity>=40?'gold':'')+pill('Thiện cảm '+p.affinity),btn('Thăm hỏi · 25 thạch','visit',p.id,'primary'),portrait(p.portrait,'card-portrait')));
if(tab==='story')cards=s.pendingEvent?[card(G.STORIES[s.pendingEvent.id].name,G.STORIES[s.pendingEvent.id].text,pill('Cốt truyện đang chờ','gold'),btn('Đưa ra lựa chọn','story','','primary'),icon('scroll'))]:[card('Tiên duyên chưa tới','Cốt truyện xuất hiện ngẫu nhiên sau 3–7 ngày game. Mối quan hệ và lựa chọn có thể khiến bạn hữu hoặc kẻ thù tìm đến.',pill('Thời gian vẫn tiếp tục'),btn('Xem quan hệ','tab','relations'),icon('users'))];
}
if(screen==='bag'){title='Hành trang tiên đồ';subtitle='Học công pháp, dùng đan dược, trang bị pháp bảo.';
if(tab==='pills')cards=G.SHOP.filter(x=>x.kind==='pill').map(x=>card(x.name,x.desc,pill('Số lượng '+(s.items[x.id]||0)),x.id==='pillBreak'?btn('Đến đột phá','nav','practice'):btn(x.id==='pillHeal'&&s.buff?'Đã dùng · chờ trận':'Dùng một viên','use',x.id,'primary',!s.items[x.id]||x.id==='pillHeal'&&s.buff),icon('pill')));
if(tab==='artifacts')cards=G.ARTIFACTS.filter(a=>s.items[a.id]>0).map(a=>card(a.name,a.desc,pill(a.grade,'gold')+pill('Số lượng '+s.items[a.id]),btn(a.id===s.artifact?'Đang trang bị':'Trang bị','equip',a.id,'primary',a.id===s.artifact),icon('sword')));
if(tab==='materials')cards=[['stone','Linh thạch','Lộ phí, luyện đan và đột phá. Nhận từ nhiệm vụ, bí cảnh.'],['herb','Linh thảo','Dược liệu luyện đan và đột phá. Thu thập khi làm nhiệm vụ, lịch luyện.'],['wood','Linh mộc','Gom từ lịch luyện, dùng khi khai sơn lập phái.'],['ore','Linh khoáng','Nhận từ bí cảnh và nhiệm vụ. Dùng luyện đan, khai tông.']].map(([id,name,desc])=>card(name,desc,pill(num(s[id])+' đang có','gold'),btn('Đi thu thập','nav','travel'),icon(id)));
if(tab==='log')cards=s.log.map(x=>{const c=G.calendar({gameMinutes:x.time});return card('Năm '+c.year+' · '+pad(c.day)+'/'+pad(c.month),esc(x.text),'','',icon('scroll'),'log-card');});
}
return {title,subtitle,cards};}
function realDuration(seconds){const d=Math.floor(seconds/86400),h=Math.floor(seconds%86400/3600),m=Math.floor(seconds%3600/60);return d?`${d} ngày ${h} giờ`:h?`${h} giờ ${m} phút`:`${m} phút ${Math.floor(seconds%60)} giây`;}
function screenMarkup(){const data=screenData(),layout=pageLayout(),count=Math.max(1,Math.ceil(data.cards.length/layout.size));page=Math.min(page,count-1);const list=data.cards.slice(page*layout.size,(page+1)*layout.size);const options=screen==='sect'&&state.path==='founder'?[...tabs.sect,['disciples','Đệ tử']]:tabs[screen]||[];return `<section class="function-screen"><div class="screen-head"><div><span class="eyebrow">${screen==='admission'?'KHẢO HẠCH NHẬP MÔN':screen==='bag'?'TÚI CÀN KHÔN':'TIÊN MÔN NHÀN DU'}</span><h2>${data.title}</h2><p>${data.subtitle}</p></div>${btn('Về cảnh chính','home','','back-button')}</div>${screen==='admission'?`<div class="measure-bar"><div><strong>${esc(G.rootName(state))}</strong><small>${state.potential===null?'Tư chất chưa đo':'Tư chất '+state.potential+'/100 · Linh căn '+state.root.purity+'/100'}</small></div>${btn(state.root?'Đã đo':'Đo linh căn','root','','secondary',!!state.root)}${btn(state.potential!==null?'Đã đo':'Đo tư chất','potential','','primary',!state.root||state.potential!==null)}</div>`:`<div class="screen-tabs">${options.map(([id,name])=>btn(name,'tab',id,tab===id?'tab-button active':'tab-button')).join('')}</div>`}${screen==='sect'&&state.path==='founder'&&(tab==='found'||tab==='disciples')?`<div class="foundation-strip">Tông môn: <b data-live="foundation">${num(state.foundation.stone)} thạch · ${num(state.foundation.wood)} mộc · ${num(state.foundation.ore)} khoáng</b>${tab==='disciples'?btn('Chiêu mộ','recruit','','secondary'):''}</div>`:''}<div class="card-grid" style="--cols:${layout.cols};--rows:${layout.rows}">${list.length?list.join(''):`<div class="empty-state">${icon('users')}<h3>Chưa có ${tab==='relations'?'người quen':'vật phẩm'} nào</h3><p>Đi lịch luyện, làm nhiệm vụ và khám phá bí cảnh để tìm thêm cơ duyên.</p>${btn('Đi lịch luyện','nav','travel','primary')}</div>`}</div><div class="screen-footer"><span>${data.cards.length} ${tab==='log'?'ghi chép':'mục'} · Trang ${page+1}/${count}</span><div>${btn('← Trước','page','-1','page-button',page===0)}${btn('Sau →','page','1','page-button',page>=count-1)}</div></div></section>`;}
function render(){header();$('#game-view').innerHTML=screen==='home'?homeMarkup():screenMarkup();live();}
function live(){$('#clock-hint').textContent=`${clockText()} · 1 giây = 1 phút${isPreview?' · Xem thử':''}`;const val={stone:num(state.stone),contribution:num(state.contribution),power:num(G.power(state)),calendar:clockText(),xp:num(state.xp)+' / '+num(G.goal(state)),rate:state.training?'Đang tu luyện':'Tạm nghỉ',annual:'Kỳ tiếp theo sau '+realDuration(Math.max(0,state.annualNext*G.YEAR-state.gameMinutes))};if(state.foundation)val.foundation=num(state.foundation.stone)+' thạch · '+num(state.foundation.wood)+' mộc · '+num(state.foundation.ore)+' khoáng';for(const [key,value]of Object.entries(val))document.querySelectorAll(`[data-live="${key}"]`).forEach(e=>e.textContent=value);document.querySelectorAll('[data-live="xpbar"]').forEach(e=>e.style.width=Math.min(100,state.xp/G.goal(state)*100)+'%');if(state.activity){document.querySelectorAll('[data-live="activity"]').forEach(e=>e.textContent=state.activity.name+' · '+Math.max(0,Math.ceil(state.activity.finish-state.gameMinutes))+' giây');document.querySelectorAll('[data-live="activitybar"]').forEach(e=>e.style.width=Math.min(100,(state.gameMinutes-state.activity.started)/(state.activity.finish-state.activity.started)*100)+'%');}}
function modal(title,body,kind='info'){dialogKind=kind;$('#modal-body').innerHTML=`<div class="modal-head"><div><span class="eyebrow">TU TIÊN VẤN ĐẠO</span><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close" aria-label="Đóng màn chức năng">×</button></div><div class="modal-content">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function profile(){modal('Người tìm đạo',`<div class="profile-preview">${portrait(state.portrait,'profile-art')}<div><strong>${G.realmName(state)}</strong><p>${G.rankName(state)} · ${esc(sectName())}</p><p>${G.rootName(state)}<br>Tư chất ${state.potential??'chưa đo'} · ${G.calendar(state).age} tuổi</p></div></div><label class="field-label">Tên nhân vật<input id="player-name" maxlength="28" value="${esc(state.name)}"></label><div class="profile-row"><label class="field-label">Xưng danh<select id="player-gender"><option value="male" ${state.gender==='male'?'selected':''}>Nam tu</option><option value="female" ${state.gender==='female'?'selected':''}>Nữ tu</option></select></label><label class="field-label">Diện mạo<select id="player-portrait">${['Mộc linh tiên tử','Bạch y kiếm tu','Thủy linh đạo sĩ','Hỏa linh tiên tử','Nguyệt linh đan sư','Sơn hà hộ pháp','Vân du đạo nhân'].map((n,i)=>`<option value="${i}" ${i===state.portrait?'selected':''}>${n}</option>`).join('')}</select></label></div>${btn('Lưu nhân vật','profile-save','','primary wide')}`,'profile');}
function exam(id){const sect=G.SECTS.find(x=>x.id===id);if(!state.root||state.potential===null){toast('Hãy đo linh căn và tư chất trước.');return;}const e=G.beginExam(state,id);if(e){toast(e);return;}persist();examQuestion();}
function examQuestion(){const x=state.exam;if(!x)return;const chosen=G.SECTS.find(c=>c.id===x.sectId),question=G.EXAM_QUESTIONS[x.phase];modal(chosen.name,`<div class="exam-summary">${icon('mountain')}${pill('Đạo tâm · '+(x.phase+1)+'/3','gold')}${pill('Điểm '+G.examScore(state,chosen.id)+(chosen.min?' · Cần '+chosen.min:' · Đạt ngưỡng'))}</div><p class="dialog-intro">${question.text}</p><div class="choice-list">${question.choices.map((text,i)=>btn(`<span>${i+1}</span>${text}`,'exam-choice',i,'choice-button')).join('')}</div><p class="modal-note">Linh căn và tư chất giữ nguyên khi khảo hạch lại. Tông môn xét cả tư chất lẫn đạo tâm.</p>`,'exam');}
function story(){if(!state.pendingEvent){toast('Chưa có cơ duyên đang chờ.');return;}const e=state.pendingEvent,d=G.STORIES[e.id],p=state.contacts.find(x=>x.id===e.personId);modal(d.name,`${p?`<div class="npc-preview">${portrait(p.portrait,'avatar')}<strong>${esc(p.name)} · ${G.relationship(p)}</strong></div>`:''}<p class="dialog-intro">${d.text}</p><div class="choice-list">${d.options.map((t,i)=>btn(t,'event-choice',i,'choice-button')).join('')}</div>`,'story');}
function battleMarkup(){const b=state.battle;if(!b)return '';const fighter=(f,cls)=>`<div class="fighter ${cls}"><h3>${esc(f.name)}</h3><div class="fighter-hp"><i style="width:${f.hp/f.maxHp*100}%"></i></div><small>${num(f.hp)} / ${num(f.maxHp)}</small>${portrait(f.portrait,'fighter-art')}<span class="fighter-energy">${'●'.repeat(f.energy)}${'○'.repeat(3-f.energy)}</span></div>`;const r=b.result;return `<div class="battle-summary">${pill(b.type==='annual'?'Đại tỷ · Vòng '+(b.tournamentRound+1):b.type==='promotion'?'Khảo hạch chức danh':b.type==='event'?'Giải quyết ân oán':'Khám phá bí cảnh','gold')}<span>Lượt ${b.round}</span></div><div class="battle-arena">${fighter(b.hero,'ally')}<span class="vs">VS</span>${fighter(b.enemy,'enemy')}</div><p class="battle-event">${esc(b.events[0]?.text||'Hai bên chuẩn bị giao đấu. Kỹ năng tự thi triển sau ba lượt.')}</p>${b.status==='fighting'?`<div class="battle-controls"><span>Chiến đấu tự động</span>${btn('Tốc độ ×'+battleSpeed,'speed')}</div>`:`<div class="battle-result"><strong>${r?.won?'Chiến thắng!':'Dưỡng sức, tu luyện rồi trở lại'}</strong><p>${r?.won?Object.entries(r.reward).filter(([k,v])=>v>0).map(([k,v])=>'+'+num(v)+' '+({stone:'linh thạch',contribution:'cống hiến',herb:'linh thảo',ore:'linh khoáng',xp:'tu vi'}[k]||k)).join(' · '):'Bạn trở về an toàn. Không mất vật phẩm đã trang bị.'}${r?.loot?'<br>Nhận '+G.itemName(r.loot):''}</p>${b.type==='annual'&&state.tournament?btn('Thi đấu vòng tiếp theo','battle','annual','primary'):btn('Trở về tiên đồ','close','','primary')}</div>`}`;}
function showBattle(){if(!state.battle)return;modal('Linh lực giao phong',battleMarkup(),'battle');if(state.battle.status==='fighting')startBattleTimer();}
function startBattleTimer(){if(battleTimer)clearInterval(battleTimer);battleTimer=setInterval(()=>{if(state.battle?.status!=='fighting'){clearInterval(battleTimer);battleTimer=null;return;}G.battleStep(state);persist();if($('#modal').open&&dialogKind==='battle')$('#modal .modal-content').innerHTML=battleMarkup();if(state.battle.status!=='fighting'){clearInterval(battleTimer);battleTimer=null;render();}},650/battleSpeed);}
function settings(){modal('Cài đặt & tiến trình',`<div class="settings-info"><strong>${esc(state.name)} · ${G.realmName(state)}</strong><span>${clockText()}</span><p>Tiến trình tự lưu trên trình duyệt này. Xuất bản lưu để chuyển sang máy khác.</p></div><div class="settings-actions">${btn(state.sound?'Âm thanh: Bật':'Âm thanh: Tắt','sound')}${btn('Xuất bản lưu JSON','export')}${btn('Nhập bản lưu JSON','import')}${btn('Hướng dẫn chơi','help')}</div><a class="legacy-link" href="legacy.html">Mở bản quản lý tông môn v1 và tiến trình cũ ${icon('arrow')}</a>${btn('Bắt đầu hành trình mới','reset','','danger wide')}<p class="modal-note">1 giây thực = 1 phút game. Thời gian v2 không giới hạn khi offline.</p>`,'settings');}
function help(){modal('Bắt đầu tiên đồ',`<ol class="help-list"><li><b>Nhập đạo.</b> Đo linh căn, tư chất và chọn một trong sáu tông môn. Thanh Vân Tông thu nhận mọi linh căn nếu đạo tâm đạt.</li><li><b>Tu luyện.</b> Bế quan tự tích lũy tu vi, kể cả khi offline. Tầng 9 đầy tu vi có thể đột phá.</li><li><b>Trải nghiệm.</b> Làm nhiệm vụ lấy cống hiến để đổi đồ. Đi lịch luyện, bí cảnh để tìm công pháp, đan dược và pháp bảo.</li><li><b>Tiến thân.</b> Tỷ thí thăng chức, dự đại tỷ mỗi năm. Đến Nguyên Anh có thể khai tông hoặc ở lại lên Trưởng lão, Chưởng môn.</li></ol><p class="modal-note">Các danh sách có nút Trước / Sau. Màn chính vừa khung màn hình; chức năng mở thành màn riêng.</p>${btn('Bắt đầu khám phá','close','','primary wide')}`,'help');}
function handleResult(error,success){if(error)toast(error);else{if(success)toast(success);persist();render();}return !error;}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();const a=el.dataset.action,id=el.dataset.id||'';sound();
if(a==='home')return openScreen('home');if(a==='nav'){const routes={missions:['sect','missions'],practice:['cultivation','practice'],travel:['activity','travel'],story:['activity','story']};return routes[id]?openScreen(...routes[id]):openScreen(id);}if(a==='tab'){tab=id;page=0;return render();}if(a==='page'){page=Math.max(0,page+Number(id));return render();}if(a==='close'){$('#modal').close();dialogKind='';return;}if(a==='settings')return settings();if(a==='profile')return profile();if(a==='help')return help();
if(a==='profile-save'){const name=$('#player-name').value.trim();if(!name)return toast('Hãy nhập tên nhân vật.');state.name=name.slice(0,28);state.gender=$('#player-gender').value;state.portrait=Number($('#player-portrait').value);persist();$('#modal').close();return render();}
if(a==='root'){G.measureRoot(state);persist();render();return toast('Linh căn: '+G.rootName(state));}if(a==='potential')return handleResult(G.measurePotential(state),'Đã xác định tư chất '+state.potential+'/100.');if(a==='exam')return exam(id);
if(a==='exam-choice'){const r=G.examChoice(state,Number(id));if(r.error)return toast(r.error);persist();if(r.next)return examQuestion();render();return modal(r.passed?'Đã nhập tiên môn':'Khảo hạch chưa đạt',`<div class="exam-result">${icon(r.passed?'check':'mountain')}<h3>${esc(r.sect)}</h3><p>${r.passed?'Bạn trở thành Tạp dịch, nhận Dẫn Khí Quyết, Mộc Kiếm và đan dược. Bế quan đã bắt đầu.':'Tư chất hoặc đạo tâm chưa đạt. Có thể thử lại hoặc chọn tông môn khác, linh căn và tư chất vẫn được giữ.'}</p><div>${pill('Tư chất '+r.score)+pill('Đạo tâm '+r.virtue+'/6')}</div>${btn(r.passed?'Bắt đầu tu luyện':'Chọn lại tông môn','exam-finish',r.passed?'passed':'failed','primary wide')}</div>`,'info');}
if(a==='exam-finish'){$('#modal').close();return openScreen(id==='passed'?'home':'admission');}
if(a==='training'){state.training=!state.training;G.addLog(state,state.training?'Bắt đầu bế quan.':'Tạm dừng bế quan.');persist();return render();}if(a==='meditate')return handleResult(G.meditate(state),'+ Tu vi nhờ tĩnh tâm.');if(a==='breakthrough')return handleResult(G.breakthrough(state),'Đột phá thành công!');
if(a==='mission'||a==='travel'||a==='exchange')return handleResult(G.activityStart(state,a==='mission'?'mission':a,id),'Đã bắt đầu. Hoàn thành vẫn được tính khi tắt game.');if(a==='buy')return handleResult(G.buy(state,id),'Đã đổi '+G.itemName(id));if(a==='book')return handleResult(state.learned.includes(id)?G.equip(state,id):G.learn(state,id),'Đang vận dụng '+G.itemName(id));if(a==='equip')return handleResult(G.equip(state,id),'Đã trang bị '+G.itemName(id));if(a==='use')return handleResult(G.use(state,id),'Đã dùng '+G.itemName(id));if(a==='craft')return handleResult(G.craft(state,id),'Luyện đan thành công.');if(a==='visit')return handleResult(G.visit(state,id),'Thiện cảm tăng 15.');
if(a==='dungeon'||a==='battle'){const r=G.startBattle(state,a==='dungeon'?'dungeon':id,a==='dungeon'?id:undefined);if(r.error)return toast(r.error);persist();return showBattle();}if(a==='resume-battle')return showBattle();if(a==='speed'){battleSpeed=battleSpeed===1?3:1;startBattleTimer();$('#modal .modal-content').innerHTML=battleMarkup();return;}
if(a==='story')return story();if(a==='event-choice'){const r=G.resolveEvent(state,Number(id));if(r.error)return toast(r.error);persist();render();if(r.battle)return showBattle();return modal('Dấu ấn tiên duyên',`<p class="dialog-intro">${esc(state.log[0].text)}</p>${btn('Tiếp tục hành trình','close','','primary wide')}`);}
if(a==='found')return modal('Khai sơn lập phái',`<p class="dialog-intro">Cần Nguyên Anh, 3.000 linh thạch, 120 linh mộc và 80 linh khoáng. Sau khi khai tông, bạn quản lý công trình và phân công đệ tử của riêng mình.</p><label class="field-label">Tên tông môn<input id="sect-name" maxlength="28" placeholder="Ví dụ: Vân Hải Tông"></label>${btn('Khai tông','found-confirm','','primary wide')}`,'found');
if(a==='found-confirm'){const ok=handleResult(G.foundSect(state,$('#sect-name').value),'Đã khai sơn lập phái!');if(ok){$('#modal').close();openScreen('sect','found');}return;}if(a==='upgrade')return handleResult(G.foundationAction(state,'upgrade',id),'Công trình đã được nâng cấp.');if(a==='recruit')return handleResult(G.foundationAction(state,'recruit'),'Một đệ tử mới gia nhập.');
if(a==='sound'){state.sound=!state.sound;persist();return settings();}if(a==='export'){persist();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='tu-tien-van-dao-v2.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),500);return toast('Đã xuất bản lưu.');}if(a==='import')return $('#import-save').click();
if(a==='reset')return modal('Bắt đầu lại?',`<p class="dialog-intro">Hành trình v2 trên thiết bị này sẽ được thay bằng một phàm nhân mới. Hãy xuất bản lưu trước nếu muốn giữ tiến trình hiện tại.</p>${btn('Xuất bản lưu hiện tại','export','','secondary wide')}${btn('Xác nhận bắt đầu lại','reset-confirm','','danger wide')}`,'reset');if(a==='reset-confirm'){if(battleTimer)clearInterval(battleTimer);state=G.newGame();persist();$('#modal').close();return openScreen('home');}
});
document.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-job]'))handleResult(G.foundationAction(state,'assign',el.dataset.job,el.value),'Đã phân công đệ tử.');});
$('#import-save').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('Bản lưu quá lớn.');const raw=await file.text(),parsed=JSON.parse(raw);if(!G.validSave(parsed))throw Error('Bản lưu v2 không hợp lệ. Bản v1 mở trong màn quản lý cũ.');if(battleTimer)clearInterval(battleTimer);state=G.restore(raw).state;persist();$('#modal').close();openScreen('home');toast('Đã nhập tiến trình và tính thời gian offline.');if(state.battle?.status==='fighting')showBattle();}catch(e){toast(e.message||'Không đọc được bản lưu.');}event.target.value='';});
$('#modal').addEventListener('close',()=>{dialogKind='';});
let resizeTimer;addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(render,100);});
function tick(){const r=G.advance(state);if(r.changed){render();if(r.activity)toast(r.activity.name+' hoàn thành'+(r.activity.loot?' · '+G.itemName(r.activity.loot):''));}else live();if(state.battle?.status==='fighting'&&!$('#modal').open&&!$('#game-view [data-action="resume-battle"]')){const b=document.createElement('button');b.className='resume-battle';b.dataset.action='resume-battle';b.textContent='Trở lại trận đấu';$('#game-view').append(b);}persist();}
setInterval(tick,1000);addEventListener('pagehide',()=>{G.advance(state);persist();});document.addEventListener('visibilitychange',()=>{if(document.hidden){G.advance(state);persist();}else tick();});
render();persist();if(initial.offline)modal('Trở lại tiên đồ',`<p class="dialog-intro">Bạn đã vắng ${realDuration(initial.offline.seconds)}. Thế giới đã trôi thêm ${num(initial.offline.minutes)} phút trong game, gồm tu luyện và các mốc năm.</p>${initial.offline.activity?`<p>${esc(initial.offline.activity.name)} đã hoàn thành${initial.offline.activity.loot?' · Nhận '+G.itemName(initial.offline.activity.loot):''}.</p>`:''}${state.annualYears.length?'<p>Đại tỷ đã khai hội. Mở Hoạt động → Đại tỷ để tham dự.</p>':''}${btn('Tiếp tục hành trình','close','','primary wide')}`);else if(state.battle?.status==='fighting')showBattle();if(initial.recovered)toast('Bản lưu không hợp lệ. Đã mở một hành trình mới.');
